// Writes config.js for the GitHub Pages deploy of the upload build (no rebuild).
// A repo Variable overrides a field only when it is non-empty; otherwise the committed config.js value stays.
// Values are taken only from the environment and written with JSON.stringify, so they can't inject code.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import vm from 'node:vm';

const file = process.argv[2] || 'config.js';
const env = process.env;
let base = {};
if (existsSync(file)) {
  const sandbox = { window: {} };
  try { vm.runInNewContext(readFileSync(file, 'utf8'), sandbox, { timeout: 1000 }); base = sandbox.window.QENTRO_CONFIG || {}; }
  catch (e) { console.error(`::error::${file} could not be read: ${e.message}`); process.exit(1); }
}
const s = v => (typeof v === 'string' ? v.trim() : '');
const cfg = {
  googleClientId: s(base.googleClientId),
  allowedEmails: Array.isArray(base.allowedEmails) ? base.allowedEmails.map(s).filter(Boolean) : [],
  signInLogUrl: s(base.signInLogUrl),
  signInLogToken: s(base.signInLogToken),
};
const v = k => s(env[k]);
if (v('VITE_GOOGLE_CLIENT_ID')) cfg.googleClientId = v('VITE_GOOGLE_CLIENT_ID');
if (v('VITE_ALLOWED_EMAILS')) cfg.allowedEmails = v('VITE_ALLOWED_EMAILS').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
if (v('VITE_SIGNIN_LOG_URL')) cfg.signInLogUrl = v('VITE_SIGNIN_LOG_URL');
if (v('VITE_SIGNIN_LOG_TOKEN')) cfg.signInLogToken = v('VITE_SIGNIN_LOG_TOKEN');

const fail = m => { console.error(`::error::${m}`); process.exit(1); };
if (cfg.googleClientId && !/^\d+-[a-z0-9]+\.apps\.googleusercontent\.com$/.test(cfg.googleClientId))
  fail('Google client ID must look like 1234567890-abc123.apps.googleusercontent.com (check the VITE_GOOGLE_CLIENT_ID variable)');
if (!cfg.googleClientId) console.log('::warning::No Google client ID set — the site will run in local-only mode.');
for (const e of cfg.allowedEmails) if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) fail(`Not an email address in VITE_ALLOWED_EMAILS: ${JSON.stringify(e)}`);
if (!cfg.allowedEmails.length) console.log('::warning::VITE_ALLOWED_EMAILS is empty — any Google account can sign in (each only reaches its own Drive).');
if (cfg.signInLogUrl && !/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(cfg.signInLogUrl))
  fail('VITE_SIGNIN_LOG_URL must be https://script.google.com/macros/s/…/exec');

writeFileSync(file, `// Generated by .github/workflows/deploy.yml from repo Variables + the committed config.js.\nwindow.QENTRO_CONFIG = ${JSON.stringify(cfg, null, 2)};\n`);
console.log(`config.js written: client ID ${cfg.googleClientId ? 'set' : 'empty'}, ${cfg.allowedEmails.length} allowed email(s), sign-in log ${cfg.signInLogUrl ? 'on' : 'off'}.`);
